<template>
  <div class="w-full space-y-5 p-4 sm:p-6">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/dashboard">Home</NuxtLink></li><li><NuxtLink to="/audits">Audit</NuxtLink></li><li>APP history</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div>
    <div v-else-if="errorMessage" class="alert alert-error"><Icon name="lucide:triangle-alert" class="h-5 w-5" />{{ errorMessage }}</div>
    <template v-else-if="record">
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body gap-4 p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-sm text-base-content/50">{{ record.item.reference_no || 'APP line item' }}</p><h1 class="mt-1 text-xl font-bold sm:text-2xl">{{ record.item.description }}</h1><p class="mt-2 text-sm text-base-content/55">APP {{ record.item.plan?.year }} · {{ record.item.plan?.company?.name }}</p></div><span class="badge badge-lg badge-outline">{{ money(record.item.total_cost) }}</span></div></div></section>
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body p-5"><h2 class="card-title text-lg">Record changes</h2><div v-if="!record.audits?.length" class="mt-5 rounded-xl border border-dashed border-base-300 py-12 text-center text-sm text-base-content/50">No field changes have been recorded for this APP line.</div><ul v-else class="timeline timeline-vertical timeline-compact mt-5"><li v-for="audit in record.audits" :key="audit.id"><div class="timeline-middle"><span class="grid h-7 w-7 place-items-center rounded-full bg-primary text-primary-content"><Icon name="lucide:file-pen-line" class="h-3.5 w-3.5" /></span></div><div class="timeline-end timeline-box mb-5 w-full max-w-4xl border-base-200 bg-base-100"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold">{{ auditTitle(audit) }}</p><p class="mt-1 text-sm text-base-content/55">{{ audit.actor?.name || 'Automated system action' }}</p></div><time class="text-xs text-base-content/50">{{ dateTime(audit.occurred_at) }}</time></div><div v-if="visibleChanges(audit).length" class="mt-4 overflow-hidden rounded-lg border border-base-200"><div v-for="change in visibleChanges(audit)" :key="change.field" class="grid gap-1 border-b border-base-200 px-3 py-2.5 last:border-b-0 sm:grid-cols-[minmax(9rem,0.7fr)_1fr]"><p class="text-xs font-medium text-base-content/55">{{ change.label }}</p><div v-if="audit.event === 'created'" class="text-sm font-medium">{{ formatValue(change.newValue, change.field) }}</div><div v-else class="flex min-w-0 items-center gap-2 text-sm"><span class="truncate text-base-content/45 line-through">{{ formatValue(change.oldValue, change.field) }}</span><Icon name="lucide:arrow-right" class="h-3.5 w-3.5 shrink-0 text-base-content/35" /><span class="truncate font-medium">{{ formatValue(change.newValue, change.field) }}</span></div></div></div><p v-else class="mt-3 text-sm text-base-content/45">No business fields changed.</p></div><hr /></li></ul></div></section>
    </template>
  </div>
</template>
<script setup>
definePageMeta({ layout: 'default', sanctum: { authOnly: true } })
useHead({ title: 'APP audit history' })
const route = useRoute(); const api = useAuditHelper(); const { canAccess } = useCheckPermission('peaudits')
const loading = ref(true); const errorMessage = ref(''); const record = ref(null)
const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase())
const money = value => new Intl.NumberFormat('en-ZW', { style: 'currency', currency: 'USD' }).format(Number(value || 0))
const dateTime = value => value ? new Intl.DateTimeFormat('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'
const fieldLabels = { description: 'Description', quantity: 'Quantity', unit_cost: 'Unit cost', total_cost: 'Planned value', quarter: 'Quarter', award_type: 'Award type', expensecategory: 'Expense category', pre_qualification: 'Pre-qualification required', eoi: 'Expression of interest', spoc: 'SPOC oversight', sustainable_procurement: 'Sustainable procurement', affirmative_procurement: 'Affirmative procurement', procurement_exemption: 'Procurement exemption', eoi_publication_date: 'EOI publication date', eoi_closing_date: 'EOI closing date', bid_notice_publication_date: 'Bid notice publication date', bid_closing_date: 'Bid closing date', publish_award_notice: 'Award notice date', contract_signing: 'Contract signing date', cycle_days: 'Procurement cycle days', lead_time_days: 'Lead time days', msds: 'Minimum service delivery standard' }
const visibleChanges = audit => [...new Set([...Object.keys(audit.old_values || {}), ...Object.keys(audit.new_values || {})])].filter(field => fieldLabels[field] && (audit.event !== 'created' || ![false, null, ''].includes(audit.new_values?.[field])) && audit.old_values?.[field] !== audit.new_values?.[field]).map(field => ({ field, label: fieldLabels[field], oldValue: audit.old_values?.[field], newValue: audit.new_values?.[field] }))
const auditTitle = audit => audit.event === 'created' ? 'APP line created' : audit.event === 'updated' ? 'APP line updated' : audit.event === 'deleted' ? 'APP line deleted' : label(audit.event)
const formatValue = (value, field) => { if (value === null || value === undefined || value === '') return 'Not set'; if (typeof value === 'boolean') return value ? 'Yes' : 'No'; if (['unit_cost', 'total_cost'].includes(field)) return money(value); if (Array.isArray(value)) return value.join(', ') || 'None'; return label(String(value)) }
onMounted(async () => { if (!canAccess.value) { errorMessage.value = 'You do not have permission to view PE audit records.'; loading.value = false; return } const { data, error } = await api.getAppItem(route.params.uuid); loading.value = false; if (error || data?.status === false) errorMessage.value = error?.data?.message || data?.message || 'APP audit history could not be loaded.'; else record.value = data.data })
</script>
